      if grid*T*U < n//4: grid=cdiv(n//4,T*U)
      fn=lambda a,b,c,d,kn=kn,grid=grid,n=n,T=T: K[kn]((grid,),(T,),a,b,c,d,bp.i64(n))
      if rep==0:
        o.zero_(); fn(g,x,s,o); torch.cuda.synchronize()
        ref=g*(s*(1+x*(1-s))); assert torch.equal(o,ref), vn
      res.setdefault((n,vn),[]).append(bp.harness_time(fn,[g,x,s],[o],warmup=5,rep=30))
  if time.time()-t0>80: break
print('reps',rep+1,'time',time.time()-t0)
print('variant  ' + ' '.join(f"{n*16/1e6:7.2f}" for n in sizes))
for vn in cfgs(1<<20):
  print(f"{vn:9s}"+' '.join(f"{st.median(res[(n,vn)]):7.2f}" for n in sizes))

